    "r90.a77f2d2326e3": "<span class=\"abadge\">{{svg1}}Keine Gebühr, jemals</span><span class=\"abadge\">{{svg2}}Einer von 300 Sitzen</span><span class=\"abadge\">Menschliche Prüfung vorgesehen</span>",
